$p = '.\app\src\main\res' if (-not (Test-Path $p)) { Write-Output "Res folder not found at $p" exit 1 } Write-Output "Scanning XML resource files under $p ..." $matches = @() Get-ChildItem -Path $p -Filter *.xml -Recurse | ForEach-Object { $file = $.FullName $content = Get-Content $file -Raw $rx = [regex] 'name="([^"]+)"' foreach ($m in $rx.Matches($content)) { $matches += [PSCustomObject]@{ Name = $m.Groups[1].Value; File = $file } } } $groups = $matches | Group-Object Name | Where-Object { $.Count -gt 1 } | Sort-Object Count -Descending if ($groups.Count -eq 0) { Write-Output "No duplicate resource names found across XML resource files." exit 0 } Write-Output "Duplicate resource names (name : count) and locations:" foreach ($g in $groups) { Write-Output "DUPLICATE: $($g.Name) : $($g.Count)" ($g.Group | Select-Object -ExpandProperty File | Sort-Object -Unique) | ForEach-Object { Write-Output " $_" } Write-Output "" }